const MOBILE_USER_AGENT_PATTERN =
  /android|iphone|ipad|ipod|windows phone|iemobile|opera mini|mobile|tablet/iu;
const TOUCH_VIEWPORT_FALLBACK_QUERY = '(hover: none) and (max-width: 1024px)';
const DEBUG_QUERY_PARAM = 'debug';

function resolvePreferredErudaTheme() {
  return document.documentElement?.dataset.theme === 'light' ? 'Light' : 'Dark';
}

function matchesMediaQuery(query: string) {
  return Boolean(globalThis.matchMedia?.(query).matches);
}

function isDebugQueryEnabled() {
  const searchParams = new URLSearchParams(globalThis.location?.search || '');

  return searchParams.get(DEBUG_QUERY_PARAM)?.trim().toLowerCase() === 'true';
}

function shouldBootstrapMobileEruda({
  isMobileDevice = isLikelyMobileBrowser(),
} = {}) {
  return isMobileDevice && isDebugQueryEnabled();
}

function isLikelyMobileBrowser() {
  if (globalThis.navigator?.userAgentData?.mobile === true) {
    return true;
  }

  const userAgent = globalThis.navigator?.userAgent || '';

  if (MOBILE_USER_AGENT_PATTERN.test(userAgent)) {
    return true;
  }

  const maxTouchPoints = Number(globalThis.navigator?.maxTouchPoints || 0);

  if (/macintosh/iu.test(userAgent) && maxTouchPoints > 1) {
    return true;
  }

  return maxTouchPoints > 0 && matchesMediaQuery(TOUCH_VIEWPORT_FALLBACK_QUERY);
}

async function initializeMobileEruda() {
  if (globalThis.__openLyricErudaInstance) {
    globalThis.__openLyricErudaInstance.get?.('entryBtn')?.show?.();
    return globalThis.__openLyricErudaInstance;
  }

  if (!shouldBootstrapMobileEruda()) {
    return null;
  }

  try {
    const importedModule = await import('eruda');
    const mobileEruda = importedModule.default || importedModule;

    mobileEruda.init({
      useShadowDom: false,
      defaults: {
        theme: resolvePreferredErudaTheme(),
      },
    });
    mobileEruda.get?.('entryBtn')?.show?.();

    globalThis.__openLyricErudaInstance = mobileEruda;

    return mobileEruda;
  } catch (error) {
    console.error('Failed to initialize Eruda.', error);
    return null;
  }
}

function bootstrapMobileEruda() {
  globalThis.__openLyricErudaBootstrapPromise ??= initializeMobileEruda();

  return globalThis.__openLyricErudaBootstrapPromise;
}

export {
  bootstrapMobileEruda,
  isLikelyMobileBrowser,
  shouldBootstrapMobileEruda,
};
